import type { ClaimResult, Damage, Item } from "./claimOffice";
import { percentOf } from "./percentage";

const DEDUCTIBLE_PER_DAMAGE = 100;
const HIGH_ENCHANTMENT_CLAIM_LEVEL = 8;
const HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT = 50;
const FULL_REIMBURSEMENT_PERCENT = 100;

function reimbursementPercent(damagedItem: Item): number {
  const isHighlyEnchanted = (damagedItem.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_LEVEL;
  return isHighlyEnchanted ? HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT : FULL_REIMBURSEMENT_PERCENT;
}

function coveredItemsFor(insuredItems: Item[], damages: Damage[]): Item[] {
  const uncoveredItems = [...insuredItems];
  return damages.map((damage) => {
    const index = uncoveredItems.findIndex((item) => item.type === damage.itemType);
    if (index < 0) {
      throw new Error(`Damaged item is not insured by the policy: ${damage.itemType}`);
    }
    return uncoveredItems.splice(index, 1)[0];
  });
}

function damagePayout(damage: Damage, damagedItem: Item): number {
  return percentOf(damage.amount, reimbursementPercent(damagedItem)) - DEDUCTIBLE_PER_DAMAGE;
}

function claimPayout(insuredItems: Item[], damages: Damage[], remainingCap: number): number {
  const damagedItems = coveredItemsFor(insuredItems, damages);
  const desiredPayout = damages.reduce((sum, damage, index) => sum + damagePayout(damage, damagedItems[index]), 0);
  return Math.floor(Math.min(desiredPayout, remainingCap));
}

export function settleClaim(insuredItems: Item[], damages: Damage[], remainingCap: number): ClaimResult {
  const payout = claimPayout(insuredItems, damages, remainingCap);
  return { payout, remainingCap: remainingCap - payout };
}
import { settleClaim } from "./claimPayout";
import { assertKnownItems } from "./itemCatalogue";
import { payoutCap } from "./payoutCap";
import { quotePremium } from "./quotePremium";

export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: { cause: string; damages: Damage[] };
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface QuoteResult {
  premium: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

interface Policy {
  insuredItems: Item[];
  remainingCap: number;
}

function isFollowUpContract(contractIndex: number): boolean {
  return contractIndex > 0;
}

export function runScenario(scenario: Scenario): { results: (QuoteResult | ClaimResult)[] } {
  const policies = new Map<number, Policy>();
  const results = scenario.steps.map((step, stepIndex) => {
    if (step.op === "claim") {
      const policy = policies.get(step.policy) ?? { insuredItems: [], remainingCap: 0 };
      const settlement = settleClaim(policy.insuredItems, step.incident.damages, policy.remainingCap);
      policy.remainingCap = settlement.remainingCap;
      return settlement;
    }
    assertKnownItems(step.items);
    policies.set(stepIndex, { insuredItems: step.items, remainingCap: payoutCap(step.items) });
    return { premium: quotePremium(scenario.customer, step.items, isFollowUpContract(stepIndex)) };
  });
  return { results };
}
import type { Item } from "./claimOffice";
import { insuranceValue } from "./itemCatalogue";

const CAP_MULTIPLIER = 2;

export function payoutCap(items: Item[]): number {
  const insuranceSum = items.reduce((sum, item) => sum + insuranceValue(item), 0);
  return insuranceSum * CAP_MULTIPLIER;
}
